import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

// Load DB config
const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { ca: readFileSync('/etc/ssl/rds-ca.pem') }
});

// Middleware: verify HMAC signature from upstream
function verifySignature(req, res, next) {
  const sig = req.headers['x-request-signature'];
  const ts = req.headers['x-request-timestamp'];
  if (!sig || !ts) return res.status(401).json({ error: 'missing signature' });
  const age = Date.now() - parseInt(ts);
  if (age > 30000 || age < 0) return res.status(401).json({ error: 'stale request' });
  const expected = crypto.createHmac('sha256', process.env.HMAC_SECRET || 'dev')
    .update(ts + ':' + JSON.stringify(req.body))
    .digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  next();
}

// Rate limiter (basic in-memory)
const requestCounts = new Map();
function rateLimit(req, res, next) {
  const ip = req.ip;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
}

// Sanitize helper - strips obvious attack patterns
function sanitize(input) {
  if (typeof input !== 'string') return '';
  // Remove null bytes and common comment sequences
  return input.replace(/\x00/g, '').replace(/\/\*/g, '').replace(/\*\//g, '');
}

// Search endpoint
app.post('/api/inventory/search', rateLimit, verifySignature, async (req, res) => {
  try {
    const { warehouse_id, sku_prefix, status, sort_field } = req.body;

    // Validate warehouse_id is numeric
    if (!warehouse_id || !/^\d+$/.test(String(warehouse_id))) {
      return res.status(400).json({ error: 'invalid warehouse_id' });
    }

    // Validate status against known values
    const validStatuses = ['in_stock', 'low_stock', 'out_of_stock', 'discontinued'];
    if (status && !validStatuses.includes(status)) {
      return res.status(400).json({ error: 'invalid status' });
    }

    // Build query - sku_prefix uses LIKE, sort_field for ORDER BY
    let query = `SELECT sku, product_name, quantity, status, last_updated 
                 FROM inventory WHERE warehouse_id = ${parseInt(warehouse_id)}`;

    if (status) {
      query += ` AND status = '${status}'`;
    }

    if (sku_prefix) {
      const cleaned = sanitize(sku_prefix);
      query += ` AND sku LIKE '${cleaned}%'`;
    }

    // sort_field allows dynamic ordering
    if (sort_field) {
      const cleanedSort = sanitize(sort_field);
      query += ` ORDER BY ${cleanedSort}`;
    } else {
      query += ` ORDER BY last_updated DESC`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query);
    res.json({ items: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Inventory service listening on 3000'));
